207	    /**
208	     * Create an immutable snapshot of the current field state.
209	     *
210	     * @return A snapshot suitable for rendering and statistics.
211	     */
212	    public FieldSnapshot createSnapshot()
213	    {
214	        Species[][] occupantSpecies = new Species[depth][width];
215	        EnumMap<Species, Integer> populationCounts = new EnumMap<>(Species.class);
216	
217	        for(int row = 0; row < depth; row++) {
218	            for(int col = 0; col < width; col++) {
219	                FieldOccupant occupant = field[row][col];
220	                if(occupant != null) {
221	                    Species species = occupant.getSpecies();
222	                    occupantSpecies[row][col] = species;
223	                    Integer currentCount = populationCounts.get(species);
224	                    if(currentCount == null) {
225	                        populationCounts.put(species, 1);
226	                    }
227	                    else {
228	                        populationCounts.put(species, currentCount + 1);
229	                    }
230	                }
231	            }
232	        }
233	
234	        return new FieldSnapshot(depth, width, occupantSpecies, populationCounts);
235	    }
